import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.BjkiRu3Q.js";const g=JSON.parse('{"title":"Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"release-notes/index.md","filePath":"release-notes/index.md"}'),s={name:"release-notes/index.md"};function o(r,e,l,d,c,p){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="release-notes" tabindex="-1">Release Notes <a class="header-anchor" href="#release-notes" aria-label="Permalink to &quot;Release Notes&quot;">​</a></h1><h2 id="v0-7-11-—-controlled-staging-release-24-november-2026" tabindex="-1">v0.7.11 — controlled staging release (24 November 2026) <a class="header-anchor" href="#v0-7-11-—-controlled-staging-release-24-november-2026" aria-label="Permalink to &quot;v0.7.11 — controlled staging release (24 November 2026)&quot;">​</a></h2><p>The release introduces integrated Website Studio publishing capabilities: hosting management, HTTPS verification, compilation of a selected website design, private revision preparation, verified backups and owner-authorized website updates and rollback. It includes single-use authorization and recovery protections and maintains independent local design studio compatibility.</p><p><strong>Availability:</strong> published software release for guarded staging deployment only. This is not evidence of an active customer website, live booking or payment processing. The release does not include database migrations or production website changes.</p><h2 id="v0-7-10-—-controlled-staging-release-24-november-2026" tabindex="-1">v0.7.10 — controlled staging release (24 November 2026) <a class="header-anchor" href="#v0-7-10-—-controlled-staging-release-24-november-2026" aria-label="Permalink to &quot;v0.7.10 — controlled staging release (24 November 2026)&quot;">​</a></h2><p>Website Studio refinements include improved visual editing and responsive previews, multilingual reference websites (English, Greek, Italian, French, German and Spanish), block and inspector editing, local draft autosave, backup and recovery, tenant-isolated draft storage, portable <code>.tbsite.json</code> and <code>.tbtheme.json</code> packages and improved navigation between Website Studio and Theme Manager.</p><p><strong>Availability:</strong> published software release for controlled staging deployment only. Public website publication, server-backed website persistence requiring migration 020, live payments and external booking integrations were not activated by this release.</p><h2 id="v0-7-9-—-source-baseline" tabindex="-1">v0.7.9 — source baseline <a class="header-anchor" href="#v0-7-9-—-source-baseline" aria-label="Permalink to &quot;v0.7.9 — source baseline&quot;">​</a></h2><p>Multi-page local-first Website Studio, responsive preview, portable website and theme packages, and tenant/mode-scoped drafts. Database activation and publication are distinct acceptance steps.</p><h2 id="v0-7-8-—-historical-staging-baseline" tabindex="-1">v0.7.8 — historical staging baseline <a class="header-anchor" href="#v0-7-8-—-historical-staging-baseline" aria-label="Permalink to &quot;v0.7.8 — historical staging baseline&quot;">​</a></h2><p>The release records describe retry-safe reservation creation, optional passenger email, duplicate booking prevention and explicit messaging consent. Staging acceptance does not establish public commercial availability.</p><h2 id="version-policy" tabindex="-1">Version policy <a class="header-anchor" href="#version-policy" aria-label="Permalink to &quot;Version policy&quot;">​</a></h2><p>These notes record published and historical versions, not the current installed version or commercial availability. Other guides retain their own reference version until reviewed against a newer release. Confirm the actual version and enabled capabilities before applying instructions.</p>',13)])])}const h=a(s,[["render",o]]);export{g as __pageData,h as default};
